const APPEAR_CSS = "\n    [data-framer-appear-id],\n    [style*=\"opacity:0\"],\n    [style*=\"opacity: 0\"],\n    [style*=\"opacity:0.001\"],\n    [style*=\"opacity: 0.001\"],\n    .framer-1f7huo,\n    .framer-1calt4r,\n    .framer-xdycc2,\n    .framer-120lpx3 {\n      opacity: 1 !important;\n      visibility: visible !important;\n      filter: none !important;\n    }\n    .framer-1k966j4-container a p,\n    .framer-1k966j4-container a span,\n    .framer-1k966j4-container a div {\n      color: #111111 !important;\n      -webkit-text-fill-color: #111111 !important;\n    }\n  ";

export default function LandingPage() {
  const [mounted, setMounted] = useState(false);
  const [email, setEmail] = useState('');
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [message, setMessage] = useState('');

  useEffect(() => {
    setMounted(true);

    const updateLocalCta = () => {
      const navButtons = document.querySelectorAll('.framer-1k966j4-container a');
      navButtons.forEach((button) => {
        button.setAttribute('href', '/dashboard');
        const pTag = button.querySelector('p');
        if (pTag) {
          pTag.textContent = 'Get started';
          pTag.style.color = '#111111';
        }
        if (!button.getAttribute('data-dashboard-attached')) {
          button.setAttribute('data-dashboard-attached', 'true');
          button.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            window.location.href = '/dashboard';
          }, true);
        }
      });
    };

    updateLocalCta();
    const interval = setInterval(updateLocalCta, 300);

    // Load Framer runtime script for animations
    const script = document.createElement('script');
    script.type = 'module';
    script.src = 'https://framerusercontent.com/sites/6Be8XUFFMocrXrTlNdktXK/script_main.BAtDVUVK.mjs';
    document.body.appendChild(script);

    return () => {
      clearInterval(interval);
      if (document.body.contains(script)) {
        document.body.removeChild(script);
      }
    };
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !email.includes('@')) return;

    setStatus('loading');
    try {
      const res = await fetch('/api/waitlist', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });
      const data = await res.json();
      if (data.success) {
        setStatus('success');
        setMessage(data.message || "You're on the waitlist!");
        setEmail('');
      } else {
        setStatus('error');
        setMessage(data.error || 'Something went wrong.');
      }
    } catch (err: any) {
      setStatus('error');
      setMessage('Failed to join waitlist. Please try again.');
    }
  };

  if (!mounted) {
    return (
      <div style={{ background: '#070708', minHeight: '100vh' }} />
    );
  }

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: APPEAR_CSS }} />
      <div
        className="landing-page-container"
        suppressHydrationWarning
        dangerouslySetInnerHTML={{ __html: RAW_LANDING_HTML }}
      />
    </>
  );
}
